using UnityEngine;using UnityEditor;
public static class ImportHeavySlam {
 public static object Run(){const string path="Assets/Resources/OgreSlamHeavyV1/slam-heavy.png";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Default;i.alphaSource=TextureImporterAlphaSource.FromInput;i.alphaIsTransparency=true;i.sRGBTexture=true;i.mipmapEnabled=false;i.npotScale=TextureImporterNPOTScale.None;i.textureCompression=TextureImporterCompression.Uncompressed;i.maxTextureSize=8192;i.filterMode=FilterMode.Bilinear;i.wrapMode=TextureWrapMode.Clamp;foreach(var n in new[]{"Standalone","Android","iPhone","WebGL"})i.ClearPlatformTextureSettings(n);i.SaveAndReimport();var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(t.width!=5120||t.height!=512)throw new System.Exception("Heavy slam sheet imported at incorrect size");return new{t.width,t.height,frames=t.width/512,i.maxTextureSize,compression=i.textureCompression.ToString(),i.mipmapEnabled};}
}
